
mod metadata; mod rencoding; mod compression; mod ecc; mod render; mod decode; use anyhow::{Result, bail}; use clap::{Parser, Subcommand}; use std::path::Path; #[derive(Parser)] #[command(name = "TZZ", about = "Data to Paper - Complete A9 Binary Storage", version = "1.0.0")] struct Cli { #[command(subcommand)] command: Commands, } #[derive(Subcommand)] enum Commands { Encode { input: String, #[arg(short, long, default_value = "output.png")] output: String, }, Decode { input: String, #[arg(short, long, default_value = ".")] out_dir: String, } } fn main() -> Result<()> { let cli = Cli::parse(); match cli.command { Commands::Encode { input, output } => { let path = Path::new(&input); if !path.exists() { bail!("File not found: {}", input); } println!(" [1/5] 메타데이터 추출..."); let mut meta = metadata::D2PMetadata::from_file(path)?; let raw_data = std::fs::read(path)?; println!(" [2/5] R-Encoding (패턴 예측)..."); let r_encoded = rencoding::REncoder::encode(&raw_data); println!("️ [3/5] LZMA2 극한 압축..."); let compressed = compression::compress(&r_encoded)?; meta.compressed_size = compressed.len() as u64; println!(" [4/5] ECC 및 페이로드 조립..."); let header = meta.to_bytes(); let mut payload = header; payload.extend_from_slice(&compressed); let ecc_payload = ecc::encode_ecc(&payload); println!("️ [5/5] A9 비트맵 렌더링..."); render::render(&ecc_payload, &output)?; println!(" 성공! 원본: {}B -> R-Encoding: {}B -> LZMA2: {}B -> ECC: {}B", meta.original_size, r_encoded.len(), meta.compressed_size, ecc_payload.len()); println!(" 출력 파일: {}", output); } Commands::Decode { input, out_dir } => { println!("️ [1/5] 이미지 로드 및 이진화..."); let ecc_payload = decode::decode_image(&input)?; println!("️ [2/5] Reed-Solomon 오류 정정..."); let payload = ecc::decode_ecc(&ecc_payload)?; println!(" [3/5] 메타데이터 파싱..."); let (meta, header_size) = metadata::D2PMetadata::from_bytes(&payload)?; let compressed = &payload[header_size..]; println!("️ [4/5] LZMA2 해제 및 R-Decoding..."); let r_encoded = compression::decompress(compressed)?; let raw_data = rencoding::REncoder::decode(&r_encoded); let checksum = crc32fast::hash(&raw_data); if checksum != meta.checksum { bail!(" 체크섬 불일치! 파일이 손상되었거나 ECC 복원에 실패했습니다."); } println!(" [5/5] 파일 복원..."); let out_path = Path::new(&out_dir).join(format!("{}.{}", meta.filename, meta.extension)); std::fs::write(&out_path, &raw_data)?; println!(" 복원 완료! 파일: {}", out_path.display()); } } Ok(()) }